I define some custom XLA primitives and want to re-use the xla_encode implementation even in non-JIT contexts (so I don't need to maintain the same code twice). But I noticed that xla.apply_primitive doesn't work with unhashable types.
Test script:
from jax import abstract_arrays
from jax.core import Primitive
from jax.interpreters import xla


p = Primitive("test_primitive")


def test_primitive(x, foo):
    return p.bind(x, foo=foo)


def test_primitive_impl(x, foo):
    return xla.apply_primitive(p, x, foo=foo)


def test_primitive_xla_encode(c, x, foo):
    raise NotImplementedError()


def test_primitive_abstract_eval(x, foo):
    return abstract_arrays.ShapedArray((1,), 'float')


p.def_impl(test_primitive_impl)
p.def_abstract_eval(test_primitive_abstract_eval)
xla.backend_specific_translations["cpu"][p] = test_primitive_xla_encode


if __name__ == '__main__':
    class SomeObject:
        __hash__ = None

    import jax
    import jax.numpy as jnp
    arr = jnp.ones(1)
    obj = SomeObject()

    try:
        jax.jit(lambda x: test_primitive(x, obj))(arr)
    except NotImplementedError:
        print('JIT works')

    try:
        test_primitive(arr, obj)
    except NotImplementedError:
        print('no-JIT works')
Output:
$ python test_apply_primitive.py
JIT works
Traceback (most recent call last):
  File "foo.py", line 47, in <module>
    test_primitive(arr, obj)
  File "foo.py", line 10, in test_primitive
    return p.bind(x, foo=foo)
  File "/Users/dion/.virtualenvs/science/lib/python3.7/site-packages/jax/core.py", line 274, in bind
    return self.impl(*args, **kwargs)
  File "foo.py", line 14, in test_primitive_impl
    return xla.apply_primitive(p, x, foo=foo)
  File "/Users/dion/.virtualenvs/science/lib/python3.7/site-packages/jax/interpreters/xla.py", line 224, in apply_primitive
    compiled_fun = xla_primitive_callable(prim, *unsafe_map(arg_spec, args), **params)
TypeError: unhashable type: 'SomeObject'
Why is hashability a constraint in this case when it seems to work just fine in the jitted code path?

I noticed that cumsum is several times slower than NumPy on 1 CPU, even on large arrays.
jax.lax.scan is faster, but only works along the leading axis (#2509).
(this might be connected to #4134)
Example script
import jax
jax.config.update('jax_enable_x64', True)

import numpy as np
import jax.numpy as jnp


@jax.jit
def bench_cumsum(arr):
    return jnp.cumsum(arr, axis=0)


@jax.jit
def bench_scan(arr):
    def accumulate(carry, y):
        new_y = y + carry
        return new_y, new_y

    init = jnp.zeros(arr.shape[1:], dtype=arr.dtype)
    return jax.lax.scan(accumulate, init, arr)[1]


def bench_np(arr):
    return np.cumsum(arr, axis=0)


if __name__ == '__main__':
    import time
    shape = (360, 160, 120, 3)

    key = jax.random.PRNGKey(17)
    arr = jax.random.uniform(key, shape=shape, dtype='float64')

    res_cumsum = bench_cumsum(arr).block_until_ready()
    start = time.perf_counter()
    for _ in range(10):
        bench_cumsum(arr).block_until_ready()
    end = time.perf_counter()
    print(f'bench_cumsum: {end-start:.3f}s')

    res_scan = bench_scan(arr).block_until_ready()
    start = time.perf_counter()
    for _ in range(10):
        bench_scan(arr).block_until_ready()
    end = time.perf_counter()
    print(f'bench_scan: {end-start:.3f}s')
    np.testing.assert_allclose(res_cumsum, res_scan)

    arr_np = np.array(arr)
    start = time.perf_counter()
    for _ in range(10):
        bench_np(arr_np)
    end = time.perf_counter()
    print(f'bench_np: {end-start:.3f}s')
Output
$ taskset -c 0 python bench_cumsum.py
bench_cumsum: 6.635s
bench_scan: 0.885s
bench_np: 2.230s

